import os,json
from volatility3.plugins.windows import windows
class Deref(windows.Windows):
 def _generator(self):
  out=[]
  for sn,dn,wp,wn in self.list_windows(self.context,self.config_path,self.config['kernel']):
   if wp.vol.offset!=0xbd5b448f45b0:continue
   w=wp.dereference();row={'pointer':hex(wp.vol.offset),'object':hex(w.vol.offset),'type':w.vol.type_name,'size':w.vol.size}
   for a in ['subPointer','strName','cbwndExtra','dwUserData','spwndParent','spwndOwner','pcls','style','ExStyle','lpfnWndProc','fnid']:
    try:
     v=getattr(w,a);row[a]=str(v)
     if a=='strName': row['strName_value']=str(v.get_string())
     try:d=v.dereference();row[a+'_deref']={'address':hex(d.vol.offset),'type':d.vol.type_name}
     except Exception as e:row[a+'_derr']=str(e)
    except Exception as e:row[a+'_error']=str(e)
   lay=self.context.layers[w.vol.layer_name];row['hex']=lay.read(w.vol.offset,512,pad=True).hex();out.append(row)
  json.dump(out,open(os.environ['OUTJSON'],'w'),indent=2)
  yield from super()._generator()
PY
